<script>
export default {
  props: ['chat', 'code', 'language', 'file', 'diff-option', 'file-diff', 'files', 'project', 'finished'],
  emits: ['message-change', 'save-file', 'add-file', 'open-file', 'sub-task'],
  data() {
    return {
      showDiff: false,
      orgContent: null,
      diff: this.fileDiff,
      zoom: 1,
      // editMode: user is editing the code block as a document
      editMode: false,
      // editContent: mutable copy while editing; code prop stays untouched
      editContent: null,
      // showMonacoDiff: toggle diff preview vs plain editor while in edit mode
      showMonacoDiff: false,
      // tracks whether editContent diverges from the last saved-to-file version
      hasUnsavedFileChanges: false,
      loadingStats: false,
      stats: null,
      showCode: true,
      prevScrollTop: 0,
      // true when the view-code container is scrolled to (or near) the bottom
      isAtBottom: true
    }
  },
  computed: {
    isStreaming() {
      return !this.finished && this.code
    },
    isPatch() {
      return this.language === 'diff'
    },
    fileName() {
      return this.file?.split("/").reverse()[0]
    },
    isCommand() {
      return this.language === "bash"
    },
    fileLanguage() {
      if (!hljs.getLanguage(this.language)) {
        return "markdown"
      }
      return this.language
    },
    $api() {
      return (this.project?.$api || this.$storex.api)
    }
  },
  watch: {
    async finished() {
      if (this.finished) {
        await this.loadDiffInfo()
      }
      if (this.chat?.mode === 'vibe') {
        // In vibe mode auto-save to file when generation completes
        this.saveToFile()
      }
    },
    code() {
      this.$nextTick(() => {
        const viewCode = this.$el?.querySelector('.view-code')
        if (!viewCode) return
        if (this.isAtBottom) {
          // Keep scroll pinned to bottom as new content arrives
          viewCode.scrollTop = viewCode.scrollHeight
        } else {
          viewCode.scrollTop = this.prevScrollTop
        }
      })
    }
  },
  mounted() {
    if (this.chat?.mode === 'vibe') {
      this.showCode = false
    }
    if (this.finished) {
      this.loadDiffInfo()
    }
    const viewCode = this.$el?.querySelector('.view-code')
    if (viewCode) viewCode.addEventListener('scroll', this.saveScrollPosition)
  },
  beforeUnmount() {
    const viewCode = this.$el?.querySelector('.view-code')
    if (viewCode) viewCode.removeEventListener('scroll', this.saveScrollPosition)
  },
  methods: {
    applyPatch() {
      this.$projects.applyPatch({ patch: this.code })
    },

    async onShowDiff() {
      if (!this.diff) {
        await this.loadDiffInfo()
      }
      this.orgContent = await this.$api.files.read(this.file)
      this.showDiff = !this.showDiff
    },

    async loadDiffInfo() {
      try {
        this.loadingStats = true
        if (this.file) {
          const { diff, stats } = await this.$api.files.diff({ path: this.file, content: this.code })
          this.diff = diff
          this.stats = stats
          if (!stats && diff) {
            this.stats = 'File changes'
          }
        }
      } finally {
        this.loadingStats = false
      }
    },

    toggleMonacoDiff() {
      this.showMonacoDiff = !this.showMonacoDiff
    },

    onEdit() {
      if (this.editMode) {
        this.cancelEdit()
        return
      }
      this.editContent = this.code
      this.editMode = true
      this.showDiff = false
      this.hasUnsavedFileChanges = false
    },

    cancelEdit() {
      this.editMode = false
      this.editContent = null
      this.showMonacoDiff = false
    },

    // Called on every editor keystroke; marks file as having unsaved changes
    onEditorChange(value) {
      this.editContent = value
      this.hasUnsavedFileChanges = true
    },

    // Applies the edited content back to the chat message (document update)
    // Does NOT touch the file on disk
    applyMessageChange() {
      this.$emit('message-change', { orgContent: this.code, newContent: this.editContent })
      this.hasUnsavedFileChanges = true
      this.cancelEdit()
    },

    // Writes the current code to disk; uses editContent if editing, otherwise code prop
    saveToFile() {
      const content = this.editMode ? this.editContent : this.code
      this.$emit('save-file', { file: this.file, content })
      this.hasUnsavedFileChanges = false
      if (this.editMode) {
        this.cancelEdit()
      }
    },

    runCommand() {
      this.$storex.api.apps.runScript(this.code)
    },

    zoomOut() {
      this.zoom -= 0.1
    },

    zoomIn() {
      this.zoom += 0.1
    },

    onCopy() {
      this.$ui.copyTextToClipboard(this.code)
    },

    createSubTask() {
      const content = [
        "```" + this.fileLanguage + " " + this.file,
        this.code,
        "```"
      ].join("\n")
      this.$emit('sub-task', { file: this.file, content })
    },

    // Track scroll position and whether user is pinned to the bottom
    saveScrollPosition() {
      const viewCode = this.$el?.querySelector('.view-code')
      if (!viewCode) return
      this.prevScrollTop = viewCode.scrollTop
      // Consider "at bottom" when within 40px of the scroll end
      const distanceFromBottom = viewCode.scrollHeight - viewCode.scrollTop - viewCode.clientHeight
      this.isAtBottom = distanceFromBottom <= 40
    }
  }
}
</script>

<style>
.header-code-highlight {
  display: none !important;
}
</style>
```

### Key changes:

1. **Added `isAtBottom` data property** — initialized to `true` so new code blocks auto-scroll by default.

2. **Updated `saveScrollPosition`** — now also calculates `distanceFromBottom`. If the user is within **40px** of the bottom, `isAtBottom` is set to `true`; otherwise `false`. This lets the user scroll up to read without being interrupted.

3. **Updated `code` watcher** — instead of always restoring `prevScrollTop`, it now checks `isAtBottom` first:
   - If at bottom → scroll to `scrollHeight` (pin to bottom)
   - Otherwise → restore previous scroll position (user scrolled up intentionally)

4. **Added `beforeUnmount`** — cleans up the scroll event listener to prevent memory leaks.
